choose.otherwise:
/* RealMapper.selectTotal 전체 현황 - 최근 발송 시간 기준 */
DECLARE @d_date DATETIME SELECT @d_date = (SELECT TOP 1 IN_TIME FROM T_MSG_TRAFFIC GROUP BY IN_TIME ORDER BY IN_TIME DESC) SELECT ISNULL(REPLACE(SUBSTRING(CONVERT(CHAR(8), MAX(IN_TIME), 8), 4, 8), ':', ''), '00:00') AS IN_TIME , ISNULL(SUM(SEND_CNT), 0) AS SEND_CNT FROM T_MSG_TRAFFIC
WHERE IN_TIME <= DATEADD(N, 0, @d_date) AND IN_TIME >= DATEADD(N, -#{totalMonTime}, @d_date)
AND TABLE_CODE IN
#{code}

mapper.select:
/* RealMapper.selectRealHistList 옥션, 지마켓 전체 테이블 현황 */
SELECT ISNULL(REPLACE(SUBSTRING(CONVERT(CHAR(8), GETDATE(), 8), 4, 8), ':', ''), '00:00') IN_TIME , ISNULL(SUM(SEND_CNT), 0) SEND_CNT , ISNULL(SUM(SUCC_CNT), 0) SUCC_CNT , ISNULL(SUM(FAIL_CNT), 0) FAIL_CNT FROM T_MSG_TRAFFIC
WHERE IN_TIME <= GETDATE() AND IN_TIME >= DATEADD(N, -1, GETDATE())
AND TABLE_CODE IN
#{code}

/* RealMapper.selectRealHistTableList 테이블별 현황 */
WITH LATEST_TIME AS ( SELECT TABLE_CODE, MAX(IN_TIME) AS MAX_IN_TIME FROM T_MSG_TRAFFIC WHERE 1 = 1
AND TABLE_CODE IN
#{code}
GROUP BY TABLE_CODE ) SELECT T.TABLE_CODE AS TABLE_CODE, ISNULL(REPLACE(SUBSTRING(CONVERT(CHAR(8), t.IN_TIME, 8), 4, 5), ':', ''), '0000') AS IN_TIME, ISNULL(SUM(T.SEND_CNT), 0) AS SEND_CNT, ISNULL(SUM(T.SUCC_CNT), 0) AS SUCC_CNT, ISNULL(SUM(T.FAIL_CNT), 0) AS FAIL_CNT FROM T_MSG_TRAFFIC T JOIN LATEST_TIME L ON T.TABLE_CODE = L.TABLE_CODE AND T.IN_TIME = L.MAX_IN_TIME GROUP BY T.TABLE_CODE, T.IN_TIME ORDER BY T.TABLE_CODE
